function gateVnv2024(T){/* pkgVNV (Wall 6569 item 6): in the corrected text, a premise one line calls VOID and another line calls "not VOID", for the same side, is a CONTRADICTION; the judge changes one of the two lines. Text test on the judge's own lines (383). */try{const t=String(T||'').replace(/\\n/g,'\n').replace(/\\+"/g,'"').replace(/[*_`]+/g,'');const LAB=[[/^\s*(?:[-•]\s*|\d+[.)]\s*)?(CHALLENGE STANDING|CHALLENGER CONCEDED LINKS)\s*:/i,'CHALLENGER'],[/^\s*(?:[-•]\s*|\d+[.)]\s*)?(DEFENSE STANDING|CONCEDED LINKS)\s*:/i,'DEFENDER']];const RC=/^\s*(?:[-•]\s*|\d+[.)]\s*)?RULING\s*(?:--|:|—|–)\s*(DEFENDER|CHALLENGER)\s+premise\s+(\d+)\s*(?:--|:|—|–)\s*(NOT\s+VOID|VOID)\b/i;
 const S={};const put=(sd,n,v,l)=>{const k=sd+'|'+n;(S[k]=S[k]||{v:[],nv:[]})[v?'v':'nv'].push(l.trim().slice(0,600));};
 for(const l of t.split('\n')){const r=l.match(RC);if(r){put(r[1].toUpperCase(),+r[2],!/NOT/i.test(r[3]),l);continue;}let sd=null;for(const [re,s] of LAB)if(re.test(l)){sd=s;break;}if(!sd)continue;
  for(const seg of l.split(/(?=\bPremises?\s+\d)/i)){const m=seg.match(/^Premise\s+(\d+)\b([^]*?)(?=[.;](?:\s|$)|$)/i);if(!m)continue;const b=m[2];if(/\b(?:is|are|was)?\s*not\s+VOID\b|\bno\s+longer\s+VOID\b/i.test(b))put(sd,+m[1],false,l);else if(/\bVOID\b/.test(b)&&!/\b(?:if|whether|unless|would)\b[^.]*\bVOID\b/i.test(b))put(sd,+m[1],true,l);}}
 const out=[];for(const k in S){const x=S[k];if(!x.v.length||!x.nv.length)continue;const [sd,n]=k.split('|');out.push({key:'VNV|'+k,why:'one line calls '+sd.toLowerCase()+' premise '+n+' VOID and another calls it not VOID: '+JSON.stringify(x.v[0].slice(0,200))+' against '+JSON.stringify(x.nv[0].slice(0,200))+'. Change one of the two lines so they agree (pkgVNV).',lines:[x.v[0],x.nv[0]]});}return out;}catch(e){return [];}}
